package com.eidolon.sc.mobile;
import org.json.*;
import java.time.*;
import java.util.*;

public final class AnniversariesTests {
    static void check(boolean value,String label){if(!value)throw new AssertionError(label);}
    public static void main(String[] args)throws Exception{
        LocalDate first=LocalDate.of(2026,1,1);check(Anniversaries.occurrence(first,first)==null,"first day not a milestone");check(Anniversaries.occurrence(first,first.plusDays(98))==null,"99th is ordinary");check(Anniversaries.occurrence(first,LocalDate.of(2026,4,10)).getLong("days")==100,"100th counts first day");check(Anniversaries.occurrence(first,first.plusDays(199)).getLong("days")==200,"repeated hundredth");check(Anniversaries.occurrence(first,first.minusDays(1))==null,"nothing before first date");check(Anniversaries.occurrence(first,first.plusYears(1)).getInt("years")==1,"whole anniversary");
        LocalDate leap=LocalDate.of(2024,2,29);check(Anniversaries.occurrence(leap,LocalDate.of(2025,2,28)).getInt("years")==1,"leap anniversary Feb28");check(Anniversaries.occurrence(leap,LocalDate.of(2028,2,29)).getInt("years")==4,"leap year Feb29");check(Anniversaries.occurrence(leap,LocalDate.of(2025,3,1))==null,"no duplicate leap anniversary March1");
        long stamp=Instant.parse("2026-01-01T01:30:00Z").toEpochMilli();JSONObject personal=PersonalData.fresh().put("producer",ProducerProfile.empty().put("timeZone","Asia/Shanghai"));check(Anniversaries.record(personal,"mano",stamp,false),"new contact recorded");check(Anniversaries.start(personal,"mano").equals(first),"automatic producer timezone");check(!Anniversaries.record(personal,"mano",stamp+86400000L,false),"first timestamp never overwritten");personal.getJSONObject("producer").put("timeZone","Pacific/Honolulu");check(Anniversaries.start(personal,"mano").equals(LocalDate.of(2025,12,31)),"timezone changes recalculate automatic timestamp");
        Anniversaries.set(personal,"mano","2026-01-01",LocalDate.of(2026,10,23));check(Anniversaries.start(personal,"mano").equals(first),"manual date stable across timezone");check(Anniversaries.lines(personal,"mano",first.plusDays(99)).contains("第 100 天"),"milestone context");check(!Anniversaries.record(personal,"hiori",stamp,true)&&Anniversaries.start(personal,"hiori")==null,"old untimestamped history remains unknown");
        JSONObject envelope=new JSONObject().put("format","eidolon-android-chats").put("version",2).put("personal",personal).put("conversations",new JSONArray());Set<String> known=new HashSet<>(Arrays.asList("mano","hiori"));BackupValidator.validate(envelope,known);JSONObject restored=new JSONObject(new String(BackupCrypto.decrypt(BackupCrypto.encrypt(envelope.toString().getBytes("UTF-8"),"anniversary-backup".toCharArray()),"anniversary-backup".toCharArray()),"UTF-8"));BackupValidator.validate(restored,known);check(Anniversaries.start(restored.getJSONObject("personal"),"mano").equals(first),"encrypted backup retains meeting date");
        boolean invalid=false;try{Anniversaries.set(personal,"hiori","2026-10-24",LocalDate.of(2026,10,23));}catch(Exception e){invalid=true;}check(invalid&&Anniversaries.start(personal,"hiori")==null,"future manual date rejected without mutation");JSONObject forged=new JSONObject(personal.toString());forged.getJSONObject("firstMeetings").put("unknown",new JSONObject().put("source","manual").put("date","2026-01-01"));invalid=false;try{Anniversaries.validate(forged,known);}catch(Exception e){invalid=true;}check(invalid,"unknown backup character rejected");
        JSONObject legacy=PersonalData.fresh();Anniversaries.validate(legacy,known);check(Anniversaries.summary(legacy,first).length()==0,"legacy profile does not invent dates");JSONObject base=new JSONObject(personal.toString()),generated=new JSONObject(personal.toString()),current=new JSONObject(personal.toString());Anniversaries.set(current,"mano","2025-12-01",first);check(Anniversaries.start(PersonalMerge.merge(base,generated,current),"mano").equals(LocalDate.of(2025,12,1)),"pending reply preserves date edits");
        System.out.println("PASS anniversaries: hundredth/year/leap boundaries, timestamp timezone and manual dates, legacy unknowns, future rejection, encrypted backup, unknown IDs and concurrent date edits. No API used.");
    }
}
